INSERT INTO `products` (`id`, `categoryId`, `name`, `slug`, `description`, `basePrice`, `imageUrl`, `tag`, `isAvailable`, `isDeliveryAvailable`, `isCombo`, `sortOrder`) VALUES
  ('prod-bobo-milk-tea', 'cat-bubble-tea', 'Bobo Milk Tea', 'bobo-milk-tea', 'Creamy milk tea with chewy boba pearls. Our classic signature drink.', 450, '/products/Bobo-Milk-Tea-500u.png', 'Classic', 1, 1, 0, 0),
  ('prod-brown-sugar-boba-milk-tea', 'cat-bubble-tea', 'Brown Sugar Boba Milk Tea', 'brown-sugar-boba-milk-tea', 'Rich brown sugar syrup blended with fresh milk and boba pearls.', 480, '/products/Brown-Black-Sugar-Boba-Milk-Tea-500u.png', 'Popular', 1, 1, 0, 1),
  ('prod-blueberry-bobo-tea', 'cat-bubble-tea', 'Blueberry Bobo Tea', 'blueberry-bobo-tea', 'Refreshing blueberry tea with boba pearls.', 450, '/products/Blueberry-Bobo-Tea-500u.png', NULL, 1, 1, 0, 2),
  ('prod-grape-bobo-tea', 'cat-bubble-tea', 'Grape Bobo Tea', 'grape-bobo-tea', 'Bold grape flavour with soft boba pearls.', 650, '/products/Grape-Bobo-Tea-700ml.png', 'New', 1, 1, 0, 3),
  ('prod-strawberry-bobo-jasmine-milk-tea', 'cat-bubble-tea', 'Strawberry Bobo Jasmine Milk Tea', 'strawberry-bobo-jasmine-milk-tea', 'Delicate jasmine milk tea with strawberry and boba.', 650, '/products/Strawberry-Bobo-Jasmine-Milk-Tea-700ml.png', 'New', 1, 1, 0, 4),
  ('prod-original-milk-tea', 'cat-milk-tea', 'Original Milk Tea', 'original-milk-tea', 'Our signature milk tea – smooth, balanced and timeless.', 380, '/products/Original-Milk-Tea-500u.png', 'Signature', 1, 1, 0, 5),
  ('prod-lychee-jasmine-milk-tea', 'cat-milk-tea', 'Lychee Jasmine Milk Tea', 'lychee-jasmine-milk-tea', 'Floral jasmine milk tea with sweet lychee.', 650, '/products/Lychee-Jasmine-Tea-700ml.png', NULL, 1, 1, 0, 6),
  ('prod-fresh-lemonade', 'cat-fruit-tea', 'Fresh Lemonade', 'fresh-lemonade', 'Ice-cold freshly squeezed lemonade.', 280, '/products/Fresh-Lemonade-700ml.png', NULL, 1, 1, 0, 7),
  ('prod-jasmine-green-tea', 'cat-fruit-tea', 'Jasmine Green Tea', 'jasmine-green-tea', 'Light and floral jasmine green tea served cold.', 320, '/products/Jasmine-Green-Tea-700ml.png', NULL, 1, 1, 0, 8),
  ('prod-lemon-black-tea', 'cat-fruit-tea', 'Lemon Black Tea', 'lemon-black-tea', 'Bold black tea with a refreshing lemon twist.', 380, '/products/Lemon-Black-Tea-700ml.png', NULL, 1, 1, 0, 9),
  ('prod-lemon-green-tea', 'cat-fruit-tea', 'Lemon Green Tea', 'lemon-green-tea', 'Green tea infused with fresh lemon.', 380, '/products/Lemon-Green-Tea-700ml.png', 'New', 1, 1, 0, 10),
  ('prod-strawberry-lemon-tea', 'cat-fruit-tea', 'Strawberry Lemon Tea', 'strawberry-lemon-tea', 'Fruity strawberry blended with zesty lemon tea.', 550, '/products/Strawberry-Lemon-Tea-700ml.png', NULL, 1, 1, 0, 11),
  ('prod-strawberry-mango-lemon-tea', 'cat-fruit-tea', 'Strawberry Mango Lemon Tea', 'strawberry-mango-lemon-tea', 'Tropical mango and strawberry in a lemon tea base.', 650, '/products/Strawberry-Mango-Lemon-Tea-v2.png', 'Popular', 1, 1, 0, 12),
  ('prod-blueberry-milkshake', 'cat-milkshake', 'Blueberry Milkshake', 'blueberry-milkshake', 'Thick and creamy blueberry milkshake.', 550, '/products/Blueberry-Milkshake-500u.png', NULL, 1, 1, 0, 13),
  ('prod-strawberry-milkshake', 'cat-milkshake', 'Strawberry Milkshake', 'strawberry-milkshake', 'Classic strawberry milkshake made with real fruit.', 550, '/products/Strawberry-Milkshake-500u.png', 'Popular', 1, 1, 0, 14),
  ('prod-chocolate-oreo-milkshake', 'cat-milkshake', 'Chocolate Oreo Milkshake', 'chocolate-oreo-milkshake', 'Rich chocolate milkshake blended with Oreo cookies.', 550, '/products/Chocolate-Oreo-Milkshake.png', NULL, 1, 1, 0, 15),
  ('prod-mulberry-milkshake', 'cat-milkshake', 'Mulberry Milkshake', 'mulberry-milkshake', 'Unique mulberry flavour in a creamy milkshake.', 550, '/products/Mulberry-Milkshake.png', NULL, 1, 1, 0, 16),
  ('prod-strawberry-oreo-milkshake', 'cat-milkshake', 'Strawberry Oreo Milkshake', 'strawberry-oreo-milkshake', 'Strawberry milkshake with crushed Oreo topping.', 550, '/products/Strawberry-Oreo-Milkshake-500u.png', NULL, 1, 1, 0, 17),
  ('prod-blueberry-sundae', 'cat-sundae', 'Blueberry Sundae', 'blueberry-sundae', 'Blueberry compote over creamy vanilla ice cream.', 450, '/products/Blueberry-Sundae-360.png', NULL, 1, 1, 0, 18),
  ('prod-blueberry-chocolate-sundae', 'cat-sundae', 'Blueberry Chocolate Sundae', 'blueberry-chocolate-sundae', 'Blueberry and chocolate drizzle over ice cream.', 480, '/products/Blueberry-Chocolate-Sundae-360.png', NULL, 1, 1, 0, 19),
  ('prod-brown-sugar-boba-sundae', 'cat-sundae', 'Brown Sugar Boba Sundae', 'brown-sugar-boba-sundae', 'Our best-selling sundae with brown sugar caramel and boba.', 480, '/products/Brown-Black-Sugar-Boba-Sundae-360.png', 'Best Seller', 1, 1, 0, 20),
  ('prod-chocolate-oreo-sundae', 'cat-sundae', 'Chocolate Oreo Sundae', 'chocolate-oreo-sundae', 'Chocolate sauce, Oreo crumble and vanilla ice cream.', 520, '/products/Chocolate-Oreo-Sundae-360.png', 'Popular', 1, 1, 0, 21),
  ('prod-chocolate-biscuit-sundae', 'cat-sundae', 'Chocolate Biscuit Sundae', 'chocolate-biscuit-sundae', 'Chocolate sauce and biscuit topping over ice cream.', 420, '/products/Chocolate-Biscuit-Sundae-360.png', NULL, 1, 1, 0, 22),
  ('prod-mango-sundae', 'cat-sundae', 'Mango Sundae', 'mango-sundae', 'Fresh mango with creamy vanilla sundae.', 450, '/products/Mango-Sundae.png', NULL, 1, 1, 0, 23),
  ('prod-mango-pomelo-sago', 'cat-sundae', 'Mango Pomelo Sago', 'mango-pomelo-sago', 'Signature Hong Kong-style mango pomelo sago dessert.', 580, '/products/Mango-Pomelo-Sago.png', 'Signature', 1, 1, 0, 24),
  ('prod-oreo-chocolate-sundae', 'cat-sundae', 'Oreo Chocolate Sundae', 'oreo-chocolate-sundae', 'Double Oreo and chocolate indulgence sundae.', 520, '/products/Oreo-Chocolate-Sundae-360.png', NULL, 1, 1, 0, 25),
  ('prod-strawberry-sundae', 'cat-sundae', 'Strawberry Sundae', 'strawberry-sundae', 'Fresh strawberry coulis over vanilla ice cream.', 420, '/products/Strawberry-Sundae-360.png', NULL, 1, 1, 0, 26),
  ('prod-vanilla-ice-cream', 'cat-ice-cream', 'Vanilla Ice Cream', 'vanilla-ice-cream', 'Classic creamy vanilla soft serve.', 200, '/products/Vanilla-Ice-Cream.png', 'Rs.200 Only', 1, 1, 0, 27),
  ('prod-chocolate-ice-cream', 'cat-ice-cream', 'Chocolate Ice Cream', 'chocolate-ice-cream', 'Rich chocolate soft serve ice cream.', 200, '/products/Chocolate-Ice-Cream.png', 'Rs.200 Only', 1, 1, 0, 28),
  ('prod-mix-choco-vanilla-ice-cream', 'cat-ice-cream', 'Mix Choco Vanilla Ice Cream', 'mix-choco-vanilla-ice-cream', 'Swirled chocolate and vanilla soft serve.', 200, '/products/Mix-Choco-Vanilla-Ice-Cream.png', NULL, 1, 1, 0, 29)
